def _summ_rows():
    rows_=[];done=set()
    for a,n in summ:
        par,sub=split_area(a)
        if par:
            if par not in done:
                rows_.append(f"| **{par}** | **{sum(x for b,x in summ if split_area(b)[0]==par)}** |"); done.add(par)
            rows_.append(f"| ↳ {sub} | {n} |")
        else: rows_.append(f"| {a} | {n} |")
    return rows_
